export interface Icone {
    classe: string;
    icon: string;
    versao: '4.x' | '5.x' | '6.x';
    search?: string;
}

// Espelho da tela do CRUD de Modulo / Mapa Menu (olimpio.zip):
//   br.com.sol7.olimpio.wapper.basico.Icones  -> classe + icon
//   br.com.sol7.olimpio.util.IconesUtil.montarIcon()  -> List<Icones> listaIcons
// Versoes do Font Awesome: 4.x (fa fa-*), 5.x (fas/far/fab fa-*), 6.x (fa-solid/fa-brands fa-*).
const icone = (classe: string, versao: Icone['versao'], search?: string): Icone => ({
    classe,
    icon: classe,
    versao,
    search,
});

