export const LISTA_ICONES_SIMPLES: string[] = LISTA_ICONES.map((icone) => icone.icon);

export const iconesPorClasse = (classe: string): Icone | undefined =>
    LISTA_ICONES.find((icone) => icone.classe === classe);

// Prefixo de escopo usado para carregar o CSS da versao correspondente
// (public/vendor/fa4-scoped.css, fa5-scoped.css, fa6-scoped.css).
export const escopoPorClasse = (classe: string): string | null => {
    if (/^(fa-solid|fa-regular|fa-brands)\s/.test(classe)) return 'olim-fa6';
    if (/^(fas|far|fab)\s/.test(classe)) return 'olim-fa5';
    if (classe.startsWith('fa ')) return 'olim-fa4';
    return null;
};
